layer.css:
[data-ryt="footer"] { color: rgb(68, 68, 68); background-color: rgb(247, 247, 247); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="section"] > h2 { color: rgb(51, 51, 51); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.32; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(51, 51, 51); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-bottom: 1px solid var(--ryt-text); border-top: none }
[data-ryt="nav"] a { color: rgb(68, 68, 68); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.32; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(68, 68, 68); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 1.32; letter-spacing: normal; text-transform: capitalize; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: rgb(68, 68, 68); font-family: var(--ryt-font-body); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.32; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(68, 68, 68); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-body); font-size: 16.896px; font-weight: 400; font-style: normal; line-height: 1.32; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(51, 51, 51); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(51, 51, 51); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(51, 51, 51); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 33.792px; font-weight: 700; font-style: normal; line-height: 1.32; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(51, 51, 51); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
